40	export type Result = { premium: number } | { payout: number; remainingCap: number };
41	
42	const PROCESSING_FEE = 5;
43	
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	  rune: 25,
52	  moonstone: 25,
53	};
54	
55	/** Premiums round in the MHPCO's favour: always up. */
56	const roundPremium = (premium: number): number => Math.ceil(premium);
57	
58	/**
59	 * Exactly this many items of one type form a "building block", priced at a flat
60	 * rate instead of per item. A larger group is NOT a block -- 4 runes pay 4x25 G.
61	 */
62	const BLOCK_SIZE = 3;
63	const BLOCK_BASE_PREMIUM = 60;
64	
65	/** How many items of each type the policy covers -- the unit the block rule applies to. */
66	const countItemsPerType = (items: Item[]): Map<string, number> =>
67	  items.reduce(
68	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
69	    new Map<string, number>(),
70	  );
71	
72	/**
73	 * The per-item rate for a type. Unknown types price at 0 G for now; the spec
74	 * calls for an error (not yet tested).
75	 */
76	const basePremiumRate = (type: string): number => BASE_PREMIUMS[type] ?? 0;
77	
78	const basePremiumForType = (type: string, count: number): number =>
79	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumRate(type);
80	
81	const policyBasePremium = (items: Item[]): number =>
82	  [...countItemsPerType(items)].reduce(
83	    (total, [type, count]) => total + basePremiumForType(type, count),
84	    0,
85	  );
86	
87	/** A customer with AT LEAST this many years of business is long-standing. */
88	const LOYALTY_THRESHOLD_YEARS = 2;
89	const LOYALTY_DISCOUNT_RATE = 0.2;
90	
91	/** Every contract after the customer's first in a scenario is a follow-up. */
92	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
93	
94	const CURSE_SURCHARGE_RATE = 0.5;
95	
96	/** An enchantment AT this level or above is "high" -- level 4 carries no surcharge. */
97	const HIGH_ENCHANTMENT_LEVEL = 5;
98	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
99	
100	/** Item-scoped surcharges stack additively: a cursed, highly enchanted item pays both. */
101	const itemSurchargeRate = (item: Item): number =>
102	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
103	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
104	
105	/** Item-scoped surcharges apply to the affected item's own base premium. */
106	const itemSurchargeTotal = (items: Item[]): number =>
107	  items.reduce(
108	    (total, item) => total + basePremiumRate(item.type) * itemSurchargeRate(item),
109	    0,
110	  );
111	
112	/**
113	 * Policy-scoped modifiers stack additively, like the item-scoped ones.
114	 * Discounts join the sum as negative rates. The follow-up contract discount
115	 * will be one more term here.
116	 */
117	const isLongStanding = (customer: Customer): boolean =>
118	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
119	
120	const policyModifierTotalOf = (
121	  policyBase: number,
122	  customer: Customer,
123	  previousQuotes: number,
124	): number =>
125	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE -
126	  (isLongStanding(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0) -
127	  (previousQuotes > 0 ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0);
128	
129	/**
130	 * Policy-scoped modifiers apply to the policy base premium, never to item
131	 * surcharges.
132	 *
133	 * Returns the modifier AMOUNT, not a multiplier on the base. Folding this into
134	 * `policyBase * (1 + rate)` is algebraically identical but NOT identical in
135	 * floating point: 100 * 1.1 is 110.00000000000001, which `roundPremium` ceils
136	 * to 111 G. Keeping base and modifier as separate addends keeps the exact
137	 * values the spec's worked examples expect.
138	 */
139	const quote = (step: QuoteStep, customer: Customer, previousQuotes: number): Result => {
140	  const policyBase = policyBasePremium(step.items);
141	  return {
142	    premium: roundPremium(
143	      policyBase +
144	        policyModifierTotalOf(policyBase, customer, previousQuotes) +
145	        itemSurchargeTotal(step.items) +
146	        PROCESSING_FEE,
147	    ),
148	  };
149	};
