151	export const runScenario = (scenario: Scenario): { results: Result[] } => {
152	  const results: Result[] = [];
153	  let quotesSoFar = 0;
154	  for (const step of scenario.steps) {
155	    if (step.op !== "quote") throw new Error(`Unsupported operation: ${step.op}`);
156	    results.push(quote(step, scenario.customer, quotesSoFar));
157	    quotesSoFar += 1;
158	  }
159	  return { results };
160	};
