   * Every step so far has been a quote, so one result == one quote. Once claim
   * steps produce results too, this must count quote steps specifically.
   */
  const quotesSoFar = (): number => results.length;
  for (const step of scenario.steps) {
    if (step.op !== "quote") throw new Error(`Unsupported operation: ${step.op}`);
    results.push(quote(step, scenario.customer, quotesSoFar()));
